cssCode:
.isometric-text {
  font-size: 70px; font-weight: 900; font-family: sans-serif;
  color: #6c63ff; text-transform: uppercase;
  transform: rotateX(30deg) rotateY(-30deg);
  transition: transform 0.4s ease, text-shadow 0.4s ease;
  text-shadow: 1px 1px 0 #4a43c2, 2px 2px 0 #4a43c2, 3px 3px 0 #4a43c2, 4px 4px 0 #4a43c2, 5px 5px 0 #4a43c2, 10px 10px 15px rgba(0,0,0,0.3);
  cursor: pointer;
}
.isometric-text:hover {
  transform: rotateX(30deg) rotateY(-30deg) translateZ(20px) translateY(-10px) translateX(-10px);
  text-shadow: 1px 1px 0 #ff007f, 2px 2px 0 #ff007f, 3px 3px 0 #ff007f, 4px 4px 0 #ff007f, 5px 5px 0 #ff007f, 20px 20px 25px rgba(0,0,0,0.4);
  color: #ff3399;
}

